import"chrome://resources/ash/common/personalization/common.css.js";import"chrome://resources/ash/common/personalization/wallpaper_grid_item_element.js";import"chrome://resources/ash/common/personalization/wallpaper.css.js";import"chrome://resources/polymer/v3_0/iron-list/iron-list.js";import{assert}from"chrome://resources/js/assert.js";import{getSeaPenTemplates}from"./constants.js";import{SeaPenRouterElement}from"./sea_pen_router_element.js";import{WithSeaPenStore}from"./sea_pen_store.js";import{getTemplate}from"./sea_pen_templates_element.html.js";import{getDefaultOptions,getTemplateTokens}from"./sea_pen_utils.js";export class SeaPenTemplatesElement extends WithSeaPenStore{static get is(){return"sea-pen-templates"}static get template(){return getTemplate()}static get properties(){return{seaPenTemplates_:{type:Array,value(){return getSeaPenTemplates()}},selected_:Object,hoveredTemplate_:Object}}getAriaIndex_(i){return i+1}onTemplateSelected_(e){assert(e.model.template,"no template selected");this.selected_=e.model.template;const template=this.seaPenTemplates_.find((template=>template.id===this.selected_.id));if(template){SeaPenRouterElement.instance().selectSeaPenTemplate(template.id)}}onMouseOver_(e){this.hoveredTemplate_=e.model.template}onMouseOut_(){this.hoveredTemplate_=null}shouldShowTemplateTitle_(template,hoveredTemplate){return template===hoveredTemplate&&template?.id!=="Query"}getTemplateTokens_(template){if(!template){return[]}return getTemplateTokens(template,getDefaultOptions(template))}isChip_(token){return typeof token?.translation==="string"}}customElements.define(SeaPenTemplatesElement.is,SeaPenTemplatesElement);